const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Canada geometry (approximate bounding box)
  const canada = ee.Geometry.Rectangle([-141, 42, -52, 84]);

  // Day of year for August 3 is 215 (non-leap) or 216 (leap year)
  const dayOfYear2023 = 215; // 2023 is not a leap year
  const dayOfYear2025 = 215; // 2025 is not a leap year

  // Get MODIS Burned Area for 2023 (Jan-Aug)
  const burned2023 = ee.ImageCollection('MODIS/061/MCD64A1')
    .filterDate('2023-01-01', '2023-08-04')
    .filterBounds(canada)
    .select('BurnDate');

  const size2023 = burned2023.size().getInfo();
  console.log('2023 Images:', size2023);

  if (size2023 === 0) {
    console.log('No data for 2023 period.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Get MODIS Burned Area for 2025 (Jan-Aug)
  const burned2025 = ee.ImageCollection('MODIS/061/MCD64A1')
    .filterDate('2025-01-01', '2025-08-04')
    .filterBounds(canada);

  const size2025 = burned2025.size().getInfo();
  console.log('2025 Images:', size2025);

  if (size2025 === 0) {
    console.log('No data for 2025 period.');
    console.log('<answer>C1</answer>');
    return;
  }

  // Process 2023: mask for burns before Aug 3, count pixels
  const burned2023Mosaic = burned2023.mosaic();
  const mask2023 = burned2023Mosaic.gt(0).and(burned2023Mosaic.lte(dayOfYear2023));
  const area2023 = mask2023.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: canada,
    scale: 3000,
    maxPixels: 1e9
  }).get('BurnDate');

  const area2023Val = area2023.getInfo();

  // Process 2025: mask for burns before Aug 3, count pixels
  const burned2025Mosaic = burned2025.mosaic();
  const mask2025 = burned2025Mosaic.gt(0).and(burned2025Mosaic.lte(dayOfYear2025));
  const area2025 = mask2025.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: canada,
    scale: 3000,
    maxPixels: 1e9
  }).get('BurnDate');

  const area2025Val = area2025.getInfo();

  console.log('2023 Burned pixels:', area2023Val);
  console.log('2025 Burned pixels:', area2025Val);

  // Validate results
  if (area2023Val === null || area2025Val === null || 
      isNaN(area2023Val) || isNaN(area2025Val)) {
    console.log('Calculation failed - invalid results.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Compare areas
  if (area2025Val > area2023Val) {
    console.log('2025 burned area greater than 2023.');
    console.log('<answer>A</answer>');
  } else {
    console.log('2025 burned area NOT greater than 2023.');
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
